package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Merging a person into another on the same sheet. Only a steward may; merging a person into themselves, or
 * when either of them is retired, is refused. The merged person's claims move to the other (numbers and dates
 * kept, listed after the other's claims in the order they were added, each released from any figure a
 * statement bound); their name and aliases become the other's aliases; their patrons are added to the
 * other's (never the other themselves, no repeats); anyone naming them as patron names the other instead
 * (no repeats); their pool memberships move to the other, the shares added up (at most 100.00) where the
 * other is already a member. Their statements, holds, watchers and contact are dropped with them.
 */
@Service
public class PersonMergeService {

    private static final BigDecimal FULL_SHARE = new BigDecimal("100.00");

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final PoolMemberRepository poolMembers;
    private final AccessService access;
    private final SheetRepository sheetRows;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public PersonMergeService(PersonRepository people, PatronRepository patrons, WatchRepository watches,
            ClaimRepository claims, StatementRepository statements, PoolMemberRepository poolMembers,
            AccessService access, SheetRepository sheetRows, Rollup rollup, ApplicationEventPublisher events) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.access = access;
        this.sheetRows = sheetRows;
        this.rollup = rollup;
        this.events = events;
    }

    /** Merge the person into the other; answers with the other as they are now. */
    @Transactional
    public Person merge(String sheetId, String user, long personId, long intoId) {
        sheetRows.lockById(sheetId);
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people");
        }
        if (personId == intoId) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves");
        }
        Person from = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Person into = people.findByIdAndSheetId(intoId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "No such person"));
        if (from.isRetired() || into.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged");
        }
        Rollup.Figures before = rollup.figures(sheetId);

        List<Claim> moving = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId));
        moving.sort(Comparator.comparing(Claim::getId));
        for (Claim claim : moving) {
            claim.setPersonId(intoId);
            claim.unbind();
        }
        claims.flush();
        for (Claim claim : moving) {
            claims.relist(claim.getId());
        }

        into.addAlias(from.getName());
        from.getAliases().forEach(into::addAlias);

        mergePatrons(sheetId, personId, intoId);
        mergePools(personId, intoId);
        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        watches.flush();
        people.delete(from);
        people.flush();

        events.publishEvent(new PersonMerged(sheetId, user, from.getName(), into.getName()));
        rollup.changed(sheetId, user, before);
        return into;
    }

    /** The merged person's patrons join the other's, and whoever named the merged person names the other. */
    private void mergePatrons(String sheetId, long personId, long intoId) {
        List<Patron> theirs = patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        List<Patron> naming = patrons.findBySheetIdAndPatronIdOrderByIdAsc(sheetId, personId);
        Set<Long> intoPatrons = patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, intoId).stream()
                .map(Patron::getPatronId).collect(Collectors.toCollection(LinkedHashSet::new));
        patrons.deleteAll(theirs);
        patrons.deleteAll(naming);
        patrons.flush();
        List<Patron> added = new ArrayList<>();
        for (Patron p : theirs) {
            long patronId = p.getPatronId();
            if (patronId != intoId && intoPatrons.add(patronId)) {
                added.add(new Patron(sheetId, intoId, patronId));
            }
        }
        for (Patron p : naming) {
            long namer = p.getPersonId();
            if (namer != intoId && !patrons.existsByPersonIdAndPatronId(namer, intoId)
                    && added.stream().noneMatch(a -> a.getPersonId() == namer)) {
                added.add(new Patron(sheetId, namer, intoId));
            }
        }
        patrons.saveAllAndFlush(added);
    }

    /** The merged person's pool memberships move to the other, adding shares where the other is a member. */
    private void mergePools(long personId, long intoId) {
        Map<Long, PoolMember> intoByPool = poolMembers.findByPersonId(intoId).stream()
                .collect(Collectors.toMap(PoolMember::getPoolId, Function.identity()));
        for (PoolMember member : poolMembers.findByPersonId(personId)) {
            PoolMember existing = intoByPool.get(member.getPoolId());
            if (existing == null) {
                member.setPersonId(intoId);
            } else {
                existing.setShare(existing.getShare().add(member.getShare()).min(FULL_SHARE));
                poolMembers.delete(member);
            }
        }
        poolMembers.flush();
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.stream.Stream;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogLine;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Tags;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Transferring a person to another sheet by id. Only a steward of this sheet may; a retired person, this
 * sheet's own id, an archived other sheet, or a name, alias or contact of theirs already on the other sheet's
 * tree, is refused; except that when one person on the other sheet itself (not retired) has a name or alias of
 * theirs, the person is merged into them as a merge does: their claims listed after the other's, their name and
 * aliases joined to the other's aliases, their contact dropped. The person arrives with their grades (each from its date), terms, contact and aliases, and their
 * claims with status, dates, notes, tags, frozen figures, logs and comments; each claim that had a number
 * takes the other sheet's next one, in the order the claims were opened (by the sheet's today when each was
 * opened, then by the order they were added). Figures a statement bound are released and references dropped.
 * The person leaves this sheet entirely: their statements, holds, patron links, pool memberships and
 * watches are dropped.
 */
@Service
public class PersonTransferService {

    private final PersonRepository people;
    private final PatronRepository patrons;
    private final WatchRepository watches;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final Tags tags;
    private final StatementRepository statements;
    private final PoolMemberRepository poolMembers;
    private final AccessService access;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public PersonTransferService(PersonRepository people, PatronRepository patrons, WatchRepository watches,
            ClaimRepository claims, ClaimService claimService, Tags tags, StatementRepository statements,
            PoolMemberRepository poolMembers, AccessService access, SheetService sheets, SheetRepository sheetRows,
            Rollup rollup, ApplicationEventPublisher events) {
        this.people = people;
        this.patrons = patrons;
        this.watches = watches;
        this.claims = claims;
        this.claimService = claimService;
        this.tags = tags;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.access = access;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.rollup = rollup;
        this.events = events;
    }

    /** Transfer the person to the other sheet (started empty when its id was never used). */
    @Transactional
    public void transfer(String sheetId, String user, long personId, String toSheet) {
        if (toSheet.equals(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet");
        }
        sheets.load(toSheet, user);
        // both sheets locked in the same order, so transfers each way between them take turns
        Stream.of(sheetId, toSheet).sorted().forEach(sheetRows::lockById);
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can transfer people");
        }
        if (sheets.isArchived(toSheet)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The other sheet is archived");
        }
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred");
        }
        List<String> names = new ArrayList<>(person.getAliases());
        names.add(person.getName());
        // held to the other sheet's tree, which may hold the person themselves; one person on the other sheet
        // itself sharing a name is merged into instead
        Set<String> wanted = new HashSet<>();
        names.forEach(n -> wanted.add(n.trim().toLowerCase(Locale.ROOT)));
        Person into = null;
        for (Person other : people.findBySheetIdIn(sheets.tree(toSheet))) {
            if (other.getId().equals(person.getId())) {
                continue;
            }
            Set<String> theirs = new HashSet<>();
            theirs.add(other.getName().trim().toLowerCase(Locale.ROOT));
            other.getAliases().forEach(a -> theirs.add(a.trim().toLowerCase(Locale.ROOT)));
            if (Collections.disjoint(wanted, theirs)) {
                continue;
            }
            if (!other.getSheetId().equals(toSheet) || into != null) {
                throw new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use on the other sheet");
            }
            into = other;
        }
        if (into != null && into.isRetired()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged");
        }
        if (into == null && person.getContact() != null
                && people.existsBySheetIdAndContact(toSheet, person.getContact())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Contact already in use on the other sheet");
        }
        Rollup.Figures beforeHere = rollup.figures(sheetId);
        Rollup.Figures beforeThere = rollup.figures(toSheet);

        Person arrived;
        if (into == null) {
            Person newcomer = person.arriving(toSheet);
            newcomer.setPosition(people.maxPosition(toSheet) + 1);
            arrived = people.saveAndFlush(newcomer);
            tags.use(toSheet, arrived.getTags());
        } else {
            // merged as a merge does: their name and aliases become the other's aliases
            arrived = into;
            arrived.addAlias(person.getName());
            person.getAliases().forEach(arrived::addAlias);
            people.saveAndFlush(arrived);
        }
        // added oldest listed first, so they list on the other sheet in the order they listed here
        List<Claim> leaving = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId));
        Collections.reverse(leaving);
        List<Claim> arriving = new ArrayList<>();
        Map<Claim, String> oldNumbers = new HashMap<>();
        Map<Claim, LocalDate> openedOn = new HashMap<>();
        Map<Claim, Long> addedAs = new HashMap<>();
        for (Claim claim : leaving) {
            Claim copy = claim.arriving(toSheet, arrived.getId());
            arriving.add(copy);
            if (claim.getShownNumber() != null) {
                oldNumbers.put(copy, claim.getShownNumber());
            }
            openedOn.put(copy, openedOn(claim));
            addedAs.put(copy, claim.getId());
            tags.use(toSheet, claim.getTags());
        }
        claims.saveAllAndFlush(arriving);

        Map<String, String> renumbered = new HashMap<>();
        arriving.stream().filter(oldNumbers::containsKey)
                .sorted(Comparator.comparing(openedOn::get).thenComparing(addedAs::get))
                .forEach(claim -> {
                    claimService.numberArrived(toSheet, claim);
                    renumbered.put(oldNumbers.get(claim), claim.getShownNumber());
                });
        // a correction, or a claim split off another, names the claim it came from by its new number
        for (Claim claim : arriving) {
            if (claim.getCorrects() != null) {
                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
            }
            if (claim.getSplitFrom() != null) {
                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
            }
        }
        claims.flush();

        patrons.deleteAll(patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        patrons.deleteAll(patrons.findBySheetIdAndPatronIdOrderByIdAsc(sheetId, personId));
        poolMembers.deleteAll(poolMembers.findByPersonId(personId));
        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
        claims.deleteAll(leaving);
        claims.flush();
        people.delete(person);
        people.flush();

        events.publishEvent(new PersonTransferred(sheetId, user, person.getName(), toSheet, null));
        rollup.changed(sheetId, user, beforeHere);
        events.publishEvent(new PersonTransferred(toSheet, user, person.getName(), null, sheetId));
        if (into != null) {
            events.publishEvent(new PersonMerged(toSheet, user, person.getName(), into.getName()));
        }
        rollup.changed(toSheet, user, beforeThere);
    }

    /** The sheet's today when the claim was opened: its first status after DRAFT; its date when it has no log of it. */
    private static LocalDate openedOn(Claim claim) {
        return claim.getLog().stream().filter(l -> l.getStatus() != ClaimStatus.DRAFT).map(ClaimLogLine::getOn)
                .findFirst().orElse(claim.getDate());
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.access.AccessService;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.rate.RateTable;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The statements taken for the people on a sheet. Taking one records the person's due-total and
 * binds each of their claims that counts to the figure it has then (without its late charge, which
 * keeps following the sheet's today); a claim that does not count is released to its live figure. A
 * statement can be taken as of a date gone by, from the sheet as it stood at the end of that date.
 * A steward can cancel a person's last statement: the claims it bound are released to their live
 * figures (a figure an earlier statement bound is not restored).
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateService rates;
    private final Rollup rollup;
    private final AccessService access;
    private final DayEnds dayEnds;
    private final ApplicationEventPublisher events;

    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
            RateService rates, Rollup rollup, AccessService access, DayEnds dayEnds,
            ApplicationEventPublisher events) {
        this.dayEnds = dayEnds;
        this.access = access;
        this.rollup = rollup;
        this.statements = statements;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.events = events;
    }

    /** Every person's statements on the sheet, by person. */
    @Transactional(readOnly = true)
    public Map<Long, Statements> bySheet(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(Statement::getPersonId,
                        Collectors.collectingAndThen(Collectors.toList(), Statements::of)));
    }

    @Transactional(readOnly = true)
    public Statements forPerson(String sheetId, long personId) {
        return Statements.of(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
    }

    /** Take a statement for the person as of the sheet's today. */
    @Transactional
    public void take(String sheetId, String user, long personId) {
        take(sheetId, user, personId, null);
    }

    /**
     * Take a statement for the person as of a date on or before the sheet's today (null: as of now). Their
     * claims that counted at the end of that date are bound to the figures they had then, with that date
     * standing in for the sheet's today, and every other claim of theirs is released; the statement is
     * dated that date and records their due-total then. A date gone by takes the sheet as it stood at the
     * end of it (see {@link DayEnds}): refused when the date is after the sheet's today, or when the person
     * was not on the sheet by then.
     */
    @Transactional
    public void take(String sheetId, String user, long personId, LocalDate asOf) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        RateTable table = rates.table(sheetId);
        LocalDate on = asOf == null ? table.today() : asOf;
        if (on.isAfter(table.today())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A statement cannot be taken as of a date after today");
        }
        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        Person then;
        Map<Long, Claim> claimsThen;
        if (on.isBefore(table.today())) {
            DayEnds.SheetThen sheetThen = dayEnds.asOf(sheetId, on)
                    .filter(t -> t.people().containsKey(personId))
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
                            "The person was not on the sheet by that date"));
            then = sheetThen.people().get(personId);
            claimsThen = sheetThen.claimsOf(personId);
            table = sheetThen.table();
        } else {
            then = person;
            claimsThen = new LinkedHashMap<>();
            theirs.forEach(c -> claimsThen.put(c.getId(), c));
        }
        Rollup.Figures before = rollup.figures(sheetId);
        BigDecimal dueTotal = Dues.total(then::gradeOn, List.copyOf(claimsThen.values()), table, then.leaves());
        int counting = 0;
        for (Claim claim : theirs) {
            Claim stood = claimsThen.get(claim.getId());
            if (stood != null && Dues.counts(stood, then.leaves(), table.today())) {
                claim.bind(Dues.base(stood, then::gradeOn, table));
                counting++;
            } else {
                claim.unbind();
            }
        }
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, on, dueTotal, counting));
        events.publishEvent(new StatementTaken(sheetId, user, person.getName(), dueTotal, counting, asOf));
        rollup.changed(sheetId, user, before);
    }

    /** Cancel the person's last statement; only a steward may, and only while the person has one. */
    @Transactional
    public void cancel(String sheetId, String user, long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (access.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
        }
        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
        if (taken.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
        }
        Rollup.Figures before = rollup.figures(sheetId);
        Statement last = taken.get(taken.size() - 1);
        for (Claim claim : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
            if (claim.isStated()) {
                claim.unbind();
            }
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        events.publishEvent(new StatementCancelled(sheetId, user, person.getName(), last.getDueTotal()));
        rollup.changed(sheetId, user, before);
    }
}
